// Generated by Agent: SETUP | Framework: myrmion-AI-factory | Feature: EVOL-106 — framework-shipped adapter canary (proof at the close).
//
// Three planted cases on fixed clauses, served by a local server: no deployed app is needed.
// `gate.py proof` refuses a run whose verdicts differ from these — the adapter is broken, not the cases:
//   canary: green       judged green; under CASE_CONTROL=1 it fails on its Then.
//   canary: order       its steps out of order — judged `order` only.
//   canary: unasserted  a Then that asserts nothing — judged `asserted` only. It writes the bare step on purpose:
//                       the helper's `then` refuses it, a broken reader or converter would let it through.
// Do not edit: the clauses and titles are the ones `gate.py proof` expects.
import http from 'node:http';
import type { AddressInfo } from 'node:net';
import { test } from '@playwright/test';
import { control, expect, given, then, when } from '../support/clauses';

const PAGE = `<!doctype html><title>canary</title><button id="act">act</button><output id="out"></output>
<script>document.getElementById('act').onclick = async () => {
  const r = await fetch('/result');
  document.getElementById('out').textContent = (await r.json()).result;
};</script>`;

let server: http.Server;
let origin = '';

test.beforeAll(async () => {
  server = http.createServer((req, res) => {
    if (req.url === '/result') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ result: 'ok' }));
      return;
    }
    res.writeHead(200, { 'content-type': 'text/html' });
    res.end(PAGE);
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

test.afterAll(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

test('canary: green', async ({ page }) => {
  await control(page, '**/result', (body) => body.replace('"ok"', '"corrupted"'));
  await given('the canary page is open', async () => {
    await page.goto(`${origin}/`);
  });
  await when('the canary acts', async () => {
    await page.click('#act');
  });
  await then('the canary shows its result', async () => {
    await expect(page.locator('#out')).toHaveText('ok');
  });
});

test('canary: order', async ({ page }) => {
  await when('the canary acts', async () => {
    await page.goto(`${origin}/`);
    await page.click('#act');
  });
  await given('the canary page is open', async () => {});
  await then('the canary shows its result', async () => {
    await expect(page.locator('#out')).toHaveText('ok');
  });
});

test('canary: unasserted', async ({ page }) => {
  await given('the canary page is open', async () => {
    await page.goto(`${origin}/`);
  });
  await when('the canary acts', async () => {
    await page.click('#act');
  });
  await test.step('Then the canary shows its result', async () => {
    await page.locator('#out').textContent();
  });
});
